class_name LevelManager
extends Node

signal item_collected(current_count: int, total_required: int)
signal level_completed

@export var total_items_required: int = 3
@export_file("*.tscn") var next_level_path: String = ""

var collected_items: int = 0


func collect_item() -> void:
	collected_items += 1
	item_collected.emit(collected_items, total_items_required)


func can_complete_level() -> bool:
	return collected_items >= total_items_required


func complete_level() -> void:
	if can_complete_level():
		level_completed.emit()
		if not next_level_path.is_empty():
			get_tree().change_scene_to_file(next_level_path)

class_name WalkerEnemy
extends CharacterBody2D

@export var speed: float = 60.0
@export var gravity: float = 980.0
@export var bounce_impulse: float = -320.0
@export var damage: int = 1
@export var death_particles_scene: PackedScene = preload("res://effects/enemy_explosion.tscn")

var direction: float = 1.0

@onready var sprite: Sprite2D = $Sprite2D
@onready var edge_detector: RayCast2D = $EdgeDetector
@onready var stomp_area: Area2D = $StompArea
@onready var hit_area: Area2D = $HitArea


func _ready() -> void:
	if stomp_area:
		stomp_area.body_entered.connect(_on_stomp_area_body_entered)
	if hit_area:
		hit_area.body_entered.connect(_on_hit_area_body_entered)


func _physics_process(delta: float) -> void:
	if not is_on_floor():
		velocity.y += gravity * delta

	if is_on_wall() or (is_on_floor() and edge_detector and not edge_detector.is_colliding()):
		_turn_around()

	velocity.x = direction * speed
	move_and_slide()


func _turn_around() -> void:
	direction *= -1.0
	if sprite:
		sprite.flip_h = direction < 0.0
	if edge_detector:
		edge_detector.position.x = absf(edge_detector.position.x) * direction


func _on_stomp_area_body_entered(body: Node2D) -> void:
	if is_queued_for_deletion():
		return
	if body is CharacterBody2D and body.velocity.y >= 0.0:
		body.velocity.y = bounce_impulse
		if death_particles_scene:
			var particles := death_particles_scene.instantiate() as GPUParticles2D
			particles.global_position = global_position
			get_parent().add_child(particles)
		queue_free()


func _on_hit_area_body_entered(body: Node2D) -> void:
	if is_queued_for_deletion():
		return
	if body.is_in_group("player") and body.has_method("take_damage"):
		if body is CharacterBody2D and body.velocity.y > 0.0 and body.global_position.y < global_position.y:
			return
		body.take_damage(damage)

class_name FlyingEnemy
extends CharacterBody2D

@export var speed: float = 80.0
@export var patrol_time: float = 2.0
@export var bounce_impulse: float = -320.0
@export var damage: int = 1
@export var death_particles_scene: PackedScene = preload("res://effects/enemy_explosion.tscn")

var direction: float = 1.0

@onready var sprite: Sprite2D = $Sprite2D
@onready var patrol_timer: Timer = $PatrolTimer
@onready var stomp_area: Area2D = $StompArea
@onready var hit_area: Area2D = $HitArea


func _ready() -> void:
	if patrol_timer:
		patrol_timer.wait_time = patrol_time
		patrol_timer.timeout.connect(_on_patrol_timer_timeout)
		patrol_timer.start()

	if stomp_area:
		stomp_area.body_entered.connect(_on_stomp_area_body_entered)
	if hit_area:
		hit_area.body_entered.connect(_on_hit_area_body_entered)


func _physics_process(_delta: float) -> void:
	if is_on_wall():
		_turn_around()
		if patrol_timer:
			patrol_timer.start()

	velocity.x = direction * speed
	velocity.y = 0.0
	move_and_slide()


func _turn_around() -> void:
	direction *= -1.0
	if sprite:
		sprite.flip_h = direction < 0.0


func _on_patrol_timer_timeout() -> void:
	_turn_around()


func _on_stomp_area_body_entered(body: Node2D) -> void:
	if is_queued_for_deletion():
		return
	if body is CharacterBody2D and body.velocity.y >= 0.0:
		body.velocity.y = bounce_impulse
		if death_particles_scene:
			var particles := death_particles_scene.instantiate() as GPUParticles2D
			particles.global_position = global_position
			get_parent().add_child(particles)
		queue_free()


func _on_hit_area_body_entered(body: Node2D) -> void:
	if is_queued_for_deletion():
		return
	if body.is_in_group("player") and body.has_method("take_damage"):
		if body is CharacterBody2D and body.velocity.y > 0.0 and body.global_position.y < global_position.y:
			return
		body.take_damage(damage)

class_name PlayerFallState
extends State

@export var player: CharacterBody2D
@export var animated_sprite: AnimatedSprite2D


func enter() -> void:
	if animated_sprite:
		animated_sprite.play("fall")


func physics_update(delta: float) -> void:
	player.apply_gravity(delta)
	var direction := Input.get_axis("move_left", "move_right")
	player.apply_movement(direction, delta)

	if player.is_on_floor():
		var sprite: Node2D = animated_sprite
		if not sprite and player:
			sprite = player.get_node_or_null("Sprite2D") as Node2D
		if sprite:
			sprite.scale = Vector2(1.25, 0.75)
			var tween := player.create_tween()
			tween.tween_property(sprite, "scale", Vector2.ONE, 0.15)

		if direction != 0.0:
			transitioned.emit(self, "run")
		else:
			transitioned.emit(self, "idle")

class_name GameCamera
extends Camera2D

var _shake_timer: float = 0.0
var _shake_strength: float = 0.0


func _process(delta: float) -> void:
	if _shake_timer > 0.0:
		_shake_timer -= delta
		offset = Vector2(
			randf_range(-_shake_strength, _shake_strength),
			randf_range(-_shake_strength, _shake_strength)
		)
	else:
		offset = Vector2.ZERO


func apply_shake(strength: float = 8.0, duration: float = 0.15) -> void:
	_shake_strength = strength
	_shake_timer = duration

class_name PlayerJumpState
extends State

@export var player: CharacterBody2D
@export var animated_sprite: AnimatedSprite2D


func enter() -> void:
	if animated_sprite:
		animated_sprite.play("jump")
	var sprite: Node2D = animated_sprite
	if not sprite and player:
		sprite = player.get_node_or_null("Sprite2D") as Node2D
	if sprite:
		sprite.scale = Vector2(0.75, 1.25)
		var tween := player.create_tween()
		tween.tween_property(sprite, "scale", Vector2.ONE, 0.15)

	if player and player.has_method("play_jump_sound"):
		player.play_jump_sound()

	if player and "jump_velocity" in player:
		player.velocity.y = player.jump_velocity


func physics_update(delta: float) -> void:
	player.apply_gravity(delta)
	var direction := Input.get_axis("move_left", "move_right")
	player.apply_movement(direction, delta)

	if Input.is_action_just_released("jump") and player.velocity.y < 0.0:
		player.velocity.y *= 0.5

	if player.velocity.y >= 0.0:
		transitioned.emit(self, "fall")

